 ap=argparse.ArgumentParser();ap.add_argument('--run-id',required=True);a=ap.parse_args();root=Path(__file__).resolve().parents[2];base=root.parent;pub=root/'runs/920'/a.run_id;runtime=base/'runtime'/a.run_id;replay=runtime/'replay';program=read(pub/'FROZEN_PROGRAM.json');result=read(replay/'RESULT.json');assert result['status']=='native_sequence_completed' and result['tool_calls']==5 and result['observations']==6
