 lost=[sorted(k for k,v in b.items() if v and not c[k]) for b,c in zip(before['fixed_access'],after['fixed_access'])];front_losses=[{k:[b[k],c[k]] for k in b if c[k]<b[k]} for b,c in zip(before['front_approach_counts'],after['front_approach_counts'])];gain=after['living_free_m2']-before['living_free_m2']
 initial_coverage=all(all(row[k] for k in program['initial_preserved_targets']) for row in before['fixed_access'])
