 summary={'run_id':a.run_id,'recorded_at':datetime.now(timezone.utc).isoformat(),'status':'conditional_geometric_benefit' if passed else 'mixed_or_failed_conditional_outcome','native_tool_calls':5,'observations':6,'images':30,'original_objects_preserved':26,'non_target_objects_exactly_unchanged':23,'storage_ids_preserved':ids,'no_rescale_or_deletion':True,'rows':rows,'coverage_gate':coverage,'living_free_gain_m2':gain,'fixed_targets_lost':lost,'storage_front_coverage_losses':front_losses,'conditional_rule_passed':passed,'positive_whole_room_professional_label':False,'historical_designer_trace':False,'model_generated':False,'training_updates':0,'unknowns':program['unknowns'],'same_template_is_not_independent_project_evidence':True};save(pub/'SUMMARY.json',summary)
